private enum InitializationResult {
    case ok
    case contractVersionMismatch
    case apiChecksumMismatch
}
// Use a global variable to perform the versioning checks. Swift ensures that
// the code inside is only computed once.
private let initializationResult: InitializationResult = {
    // Get the bindings contract version from our ComponentInterface
    let bindings_contract_version = 30
    // Get the scaffolding contract version by calling the into the dylib
    let scaffolding_contract_version = ffi_dayflow_core_uniffi_contract_version()
    if bindings_contract_version != scaffolding_contract_version {
        return InitializationResult.contractVersionMismatch
    }
    if (uniffi_dayflow_core_checksum_func_canonical_device_request() != 54917) {
        return InitializationResult.apiChecksumMismatch
    }
    if (uniffi_dayflow_core_checksum_func_capture_allowed() != 58876) {
        return InitializationResult.apiChecksumMismatch
    }
    if (uniffi_dayflow_core_checksum_func_capture_decision_json() != 59226) {
        return InitializationResult.apiChecksumMismatch
    }
    if (uniffi_dayflow_core_checksum_func_core_version() != 61024) {
        return InitializationResult.apiChecksumMismatch
    }
    if (uniffi_dayflow_core_checksum_func_device_public_key() != 63838) {
        return InitializationResult.apiChecksumMismatch
    }
    if (uniffi_dayflow_core_checksum_func_device_signing_public_key() != 27839) {
        return InitializationResult.apiChecksumMismatch
    }
    if (uniffi_dayflow_core_checksum_func_export_recovery_kit_json() != 53768) {
        return InitializationResult.apiChecksumMismatch
    }
    if (uniffi_dayflow_core_checksum_func_export_recovery_kit_keyring_json() != 55339) {
        return InitializationResult.apiChecksumMismatch
    }
    if (uniffi_dayflow_core_checksum_func_generate_account_root_key() != 58413) {
        return InitializationResult.apiChecksumMismatch
    }
    if (uniffi_dayflow_core_checksum_func_generate_device_private_key() != 63774) {
        return InitializationResult.apiChecksumMismatch
    }
    if (uniffi_dayflow_core_checksum_func_generate_device_signing_private_key() != 63166) {
        return InitializationResult.apiChecksumMismatch
    }
    if (uniffi_dayflow_core_checksum_func_logical_day_key_ffi() != 41932) {
        return InitializationResult.apiChecksumMismatch
    }
    if (uniffi_dayflow_core_checksum_func_project_json() != 54121) {
        return InitializationResult.apiChecksumMismatch
    }
    if (uniffi_dayflow_core_checksum_func_project_keyring_json() != 6044) {
        return InitializationResult.apiChecksumMismatch
    }
    if (uniffi_dayflow_core_checksum_func_rekey_envelopes_json() != 58932) {
        return InitializationResult.apiChecksumMismatch
    }
    if (uniffi_dayflow_core_checksum_func_restore_recovery_key() != 22829) {
        return InitializationResult.apiChecksumMismatch
    }
    if (uniffi_dayflow_core_checksum_func_restore_recovery_keyring_json() != 43225) {
        return InitializationResult.apiChecksumMismatch
    }
    if (uniffi_dayflow_core_checksum_func_seal_json() != 50622) {
        return InitializationResult.apiChecksumMismatch
    }
    if (uniffi_dayflow_core_checksum_func_seal_json_with_key_version() != 23779) {
        return InitializationResult.apiChecksumMismatch
    }
    if (uniffi_dayflow_core_checksum_func_sign_request() != 27848) {
        return InitializationResult.apiChecksumMismatch
    }
    if (uniffi_dayflow_core_checksum_func_unwrap_account_key_json() != 600) {
