    }
    if (uniffi_dayflow_core_checksum_func_wrap_account_key_json() != 1996) {
        return InitializationResult.apiChecksumMismatch
    }
    if (uniffi_dayflow_core_checksum_func_wrap_account_key_json_with_version() != 61727) {
        return InitializationResult.apiChecksumMismatch
    }

    return InitializationResult.ok
